inputs = ['acig', 'hxyvck', 'zk', 'hibwxv', 'zbwkxe']
outputs = ['fcw', 'gzxxyvck', 'zk', 'gzxibggcaxv', 'zbggcakxe']

# Let's focus on the actual differences between strings
print("Detailed character-by-character comparison:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"\n{i}: '{inp}' -> '{out}'")

    # Find which positions differ
    diff_positions = []
    for j in range(max(len(inp), len(out))):
        in_char = inp[j] if j < len(inp) else None
        out_char = out[j] if j < len(out) else None
        if in_char != out_char:
            diff_positions.append((j, in_char, out_char))

    if diff_positions:
        for pos, in_char, out_char in diff_positions:
            print(f"  Position {pos}: '{in_char}' -> '{out_char}'")
    else:
        print("  No character differences")

